// main.js —— 入口与主游戏循环
// 职责：创建渲染器/场景/相机、管理 PointerLock、驱动每帧 update、
//        回合流程（波次刷怪 → 全清 → 下一波 → 通关/阵亡结算）
// 经典脚本（非 ES Module）：THREE / CONFIG / GameMap / Player / WeaponSystem /
//        Enemy / PickupSystem / HUD / AudioFX 均由前置脚本挂到 window 提供

class Game {
  constructor() {
    this.hud = new HUD();
    this.audio = new AudioFX();
    this.hud.audio = this.audio;

    // 横屏包装层：小工具容器/WebView 常被宿主 App 锁定为竖屏、无法跟随设备旋转
    //（skill 文档明确 requestFullscreen / orientation.lock / PointerLock 均不可用），
    // 把全部游戏 DOM 包进一层，视口为竖屏时整体 CSS 旋转 90° 强制横屏
    const gameRoot = document.createElement('div');
    gameRoot.id = 'gameRoot';
    for (const el of Array.from(document.body.children)) {
      if (el.tagName !== 'SCRIPT') gameRoot.appendChild(el);
    }
    document.body.appendChild(gameRoot);
    this.gameRoot = gameRoot;
    this._rotated = false;

    // Three 基础设施
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    // 像素比上限：触屏设备 1.5（高 DPR 手机像素压力最大，降级显著提帧率），桌面 2
    const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, isTouch ? 1.5 : 2));
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    gameRoot.appendChild(this.renderer.domElement);

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(CONFIG.fov, window.innerWidth / window.innerHeight, 0.05, CONFIG.renderDistance);
    this.scene.add(this.camera);

    // 环境贴图：程序化室内光照（PMREM），让金属枪械/装甲有真实反射，否则金属像灰塑料
    this.scene.environment = this._buildEnvironment();

    // 地图
    this.gameMap = new GameMap(this.scene);

    // 玩家
    this.player = new Player(this.camera, this.gameMap, this.hud);

    // 敌人数组（动态引用，weapon 通过此数组找目标）
    this.enemies = [];

    // 武器系统（依赖 enemies 引用）
    this.weapons = new WeaponSystem(this.scene, this.camera, this.player, this.gameMap, this.enemies, this.hud, this.audio);

    // 补给拾取系统（血包 + 弹药包，弹药包需要 weapons 引用补弹）
    this.pickups = new PickupSystem(this.scene, this.gameMap, this.player, this.hud, this.audio, this.weapons);

    // 小地图数据源（必须在 gameMap/player/enemies 都创建完后）
    this.hud.setMinimapRefs(
      this.gameMap,
      this.player,
      () => this.enemies,
      () => this.pickups ? this.pickups.pickups : []
    );

    // 游戏状态
    this.state = 'menu';   // menu / playing / paused / over
    this.wave = 0;
    this.kills = 0;
    this.totalKills = 0;
    this.startTime = 0;
    this.spawnQueue = [];
    this.spawnTimer = 0;

    // 自定义控件布局（localStorage 持久化）
    this._editLayout = false;
    this._layout = this._loadLayout();
    this._bindSettings();
    this._bindLayoutEdit();

    // 半自动射击：监听鼠标按下（pointerlock 内）
    this._bindUI();
    this._bindResize();

    // 启动渲染循环（始终运行，菜单态也渲染场景）
    this._lastTime = performance.now();
    this._loop();
  }

  // ---------- UI 绑定 ----------
  _bindUI() {
    document.getElementById('startBtn').addEventListener('click', () => this._beginRun());
    document.getElementById('restartBtn').addEventListener('click', () => {
      this.hud.hideResult();
      this._beginRun();
    });
    document.getElementById('resumeBtn').addEventListener('click', () => this._resume());

    // PointerLock
    this._onPointerLockChange = () => {
      if (document.pointerLockElement === this.renderer.domElement) {
        // 锁定中
        if (this.state === 'paused') this.state = 'playing';
        this.hud.hideClickHint();
      } else {
        // 解锁
        if (this.state === 'playing') {
          this.state = 'paused';
          this.hud.showPause();
        }
      }
    };
    document.addEventListener('pointerlockchange', this._onPointerLockChange);

    // 鼠标移动 → 玩家视角
    this._onMouseMove = (e) => {
      if (this.state === 'playing') this.player.onMouseMove(e);
    };
    document.addEventListener('mousemove', this._onMouseMove);

    // 鼠标按下：半自动武器触发一次 + 锁定
    // 触屏设备点击视角区会合成 mouse 事件导致误开火，射击一律走 FIRE 按钮
    this._isTouchDevice = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    this._onCanvasClick = () => {
      if (this._isTouchDevice) return;
      if (this.state === 'menu' || this.state === 'over') return;
      if (document.pointerLockElement !== this.renderer.domElement) {
        this._requestLock();
        return;
      }
      if (this.state === 'playing') {
        this.weapons.triggerSemi();
      }
    };
    this.renderer.domElement.addEventListener('mousedown', this._onCanvasClick);

    // 触屏视角控制（document 级，多指支持，独立于 FIRE/D-pad）
    this._lookTouchId = null;
    this._lookLastX = 0;
    this._lookLastY = 0;

    this._onDocTouchStart = (e) => {
      if (this.state !== 'playing') return;
      // 遍历新增的触点，找到一个不在控件上的 → 作为视角触点
      for (const t of e.changedTouches) {
        // 跳过控件区域（D-pad、FIRE、动作键、小地图、overlay）
        if (t.target.closest && t.target.closest('#touchControls, #minimapWrap, .overlay, #menu, #result, #pause, #topbar')) continue;
        if (this._lookTouchId === null) {
          this._lookTouchId = t.identifier;
          this._lookLastX = t.clientX;
          this._lookLastY = t.clientY;
        }
      }
    };
    // 视角滑动方向映射：整页旋转 90° 后，屏幕系位移 (dx,dy) 需转成内容系 (dy,-dx)
    // 仅当本指是"已捕获的视角指"时才 preventDefault 并消费，其他触点（摇杆/按钮/多余指）不干扰
    this._onDocTouchMove = (e) => {
      if (this.state !== 'playing' || this._lookTouchId === null) return;
      for (const t of e.changedTouches) {
        if (t.identifier === this._lookTouchId) {
          e.preventDefault();
          const dx = t.clientX - this._lookLastX;
          const dy = t.clientY - this._lookLastY;
          this._lookLastX = t.clientX;
          this._lookLastY = t.clientY;
          this.player.onTouchLook(
            this._rotated ? dy : dx,
            this._rotated ? -dx : dy
          );
          break;
        }
      }
    };
    this._onDocTouchEnd = (e) => {
      for (const t of e.changedTouches) {
        if (t.identifier === this._lookTouchId) {
          this._lookTouchId = null;
        }
      }
    };
    document.addEventListener('touchstart', this._onDocTouchStart, { passive: false });
    document.addEventListener('touchmove', this._onDocTouchMove, { passive: false });
    document.addEventListener('touchend', this._onDocTouchEnd, { passive: false });
    document.addEventListener('touchcancel', this._onDocTouchEnd, { passive: false });

    // 移动端虚拟按钮（D-pad + 动作键）→ 模拟键盘事件
    this._setupVirtualControls();

    // Esc 暂停（pointerlock 退出会自动触发，这里处理继续）
    this._onKeyDown = (e) => {
      if (e.code === 'Escape') {
        if (this._editLayout) { this._exitEditLayout(); return; }
        if (this.state === 'playing') {
          document.exitPointerLock();
        }
      }
    };
    window.addEventListener('keydown', this._onKeyDown);

    // 点击暂停界面任意处 → 重新锁定
    this.hud.pause.addEventListener('click', () => this._resume());
  }

  _setupVirtualControls() {
    const touchControls = document.getElementById('touchControls');
    const isTouchDevice = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    const isSmallScreen = window.innerWidth <= 1024;
    const forceShow = window.location.search.includes('controls=1') || window.location.search.includes('mobile=1');
    if (!touchControls) return;
    // 触屏设备 OR 小屏 OR URL 强制：进入游戏中时显示虚拟控制
    if (!isTouchDevice && !isSmallScreen && !forceShow) return;
    const origShow = this.hud.show.bind(this.hud);
    this.hud.show = () => { origShow(); touchControls.classList.remove('hidden'); };
    const origHide = this.hud.hide.bind(this.hud);
    this.hud.hide = () => { origHide(); touchControls.classList.add('hidden'); };

    // 触屏设备上浏览器会在 touch 后合成 mouse 事件，若同时绑定会导致按钮双触发，
    // 因此统一用 Pointer Events 作为唯一输入源：触屏 pointerType='touch'、鼠标 pointerType='mouse'，
    // 天然去重（不会出现 touch + 合成 mouse 双发），且多指各自带 pointerId，互不干扰
    const hasPointerEvents = ('PointerEvent' in window);
    const bindPress = (btn, press, release) => {
      if (hasPointerEvents) {
        btn.addEventListener('pointerdown', (e) => { if (e.button !== undefined && e.button !== 0 && e.pointerType === 'mouse') return; e.preventDefault(); press(e); }, { passive: false });
        btn.addEventListener('pointerup', (e) => { e.preventDefault(); release(e); }, { passive: false });
        btn.addEventListener('pointercancel', (e) => { e.preventDefault(); release(e); }, { passive: false });
        // 按住时手指滑出按钮仍应释放（避免卡住持续开火）
        btn.addEventListener('pointerleave', (e) => { if (e.pointerType === 'touch') return; release(e); });
      } else {
        btn.addEventListener('touchstart', press, { passive: false });
        btn.addEventListener('touchend', release, { passive: false });
        btn.addEventListener('touchcancel', release, { passive: false });
        if (!isTouchDevice) {
          btn.addEventListener('mousedown', press);
          btn.addEventListener('mouseup', release);
          btn.addEventListener('mouseleave', release);
        }
      }
    };

    // D-pad / 动作键 → 模拟键盘
    const fireKey = (code, down) => {
      this.player.keys[code] = down;
      if (down && code === 'KeyR') this.weapons.startReload();
    };
    // 旋转态：屏幕方向与玩家移动方向错位 90°，将 D-pad 按键映射旋转 90°（逆时针，
    // W→A→S→D→W），使视觉"上"按钮对应玩家在屏幕上的"上"方向
    const rotateDpad = (c) => {
      const map = { KeyW: 'KeyA', KeyA: 'KeyS', KeyS: 'KeyD', KeyD: 'KeyW' };
      return map[c] || c;
    };
    touchControls.querySelectorAll('[data-key]').forEach(btn => {
      const code = btn.dataset.key;
      const press = (e) => { e.preventDefault(); if (this._editLayout) return; btn.classList.add('active'); fireKey(this._rotated ? rotateDpad(code) : code, true); };
      const release = (e) => { e.preventDefault(); btn.classList.remove('active'); fireKey(this._rotated ? rotateDpad(code) : code, false); };
      bindPress(btn, press, release);
    });

    // ---- 浮动虚拟摇杆（三角洲式）：左半屏任意处按下出现，拖动输出模拟量 ----
    // 用 Pointer Events 统一鼠标与触摸（skill 跨端指引推荐），桌面可测、真机可用
    const joyZone = document.getElementById('joyZone');
    const joyBase = document.getElementById('joyBase');
    const joyKnob = document.getElementById('joyKnob');
    if (joyZone && joyBase && joyKnob) {
      const joyRadius = () => 46 * (this._ctrlScale || 1) * (this._layout.size || 1);   // 半径随控件缩放+自定义大小
      let joyId = null, cx = 0, cy = 0;
      const setKnob = (dx, dy) => {
        joyKnob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
      };
      const joyStart = (x, y, id) => {
        joyId = id;
        cx = x; cy = y;
        const rect = joyZone.getBoundingClientRect();
        // 旋转态：屏幕坐标转内容坐标（rotate 90° CW: content.x = screen.y, content.y = -screen.x），
        // 否则 joyBase/joyKnob 会被显示在错误位置
        if (this._rotated) {
          joyBase.style.left = (y - rect.top) + 'px';
          joyBase.style.top = -(x - rect.left) + 'px';
        } else {
          joyBase.style.left = (x - rect.left) + 'px';
          joyBase.style.top = (y - rect.top) + 'px';
        }
        joyBase.style.bottom = 'auto';
        joyZone.classList.add('active');
        setKnob(0, 0);
      };
      const joyMove = (x, y) => {
        const R = joyRadius();
        let dx = x - cx, dy = y - cy;
        const len = Math.hypot(dx, dy);
        if (len > R) { dx = dx / len * R; dy = dy / len * R; }
        // 旋转态：屏幕 delta 转内容 delta（content.x = dy, content.y = -dx），
        // 让 setKnob 视觉和 moveTouch 方向都跟玩家移动方向对齐
        const cdx = this._rotated ? dy : dx;
        const cdy = this._rotated ? -dx : dy;
        setKnob(cdx, cdy);
        // 模拟量：x 右 / y 前（内容 y 向下为正，前推为负 → 取反）
        this.player.moveTouch.x = cdx / R;
        this.player.moveTouch.y = -cdy / R;
      };
      const joyEnd = () => {
        joyId = null;
        joyZone.classList.remove('active');
        setKnob(0, 0);
        joyBase.style.left = ''; joyBase.style.top = ''; joyBase.style.bottom = '';
        this.player.moveTouch.x = 0; this.player.moveTouch.y = 0;
      };
      joyZone.addEventListener('pointerdown', (e) => {
        if (joyId !== null || this._editLayout) return;
        e.preventDefault();
        // 捕获指针：拖出摇杆区后 move/up 仍派发给本元素（鼠标尤其需要）
        if (joyZone.setPointerCapture) {
          try { joyZone.setPointerCapture(e.pointerId); } catch (err) { /* 忽略 */ }
        }
        joyStart(e.clientX, e.clientY, e.pointerId);
      });
      joyZone.addEventListener('pointermove', (e) => {
        if (joyId === null || e.pointerId !== joyId) return;
        e.preventDefault();
        joyMove(e.clientX, e.clientY);
      });
      const joyPointerEnd = (e) => {
        if (e.pointerId !== joyId) return;
        joyEnd();
      };
      joyZone.addEventListener('pointerup', joyPointerEnd);
      joyZone.addEventListener('pointercancel', joyPointerEnd);
    }

    // FIRE 按钮：按下触发半自动 + 标记自动射击；松开停止自动
    touchControls.querySelectorAll('[data-action="fire"]').forEach(btn => {
      const press = (e) => {
        e.preventDefault(); if (this._editLayout) return;
        btn.classList.add('active');
        this.weapons.triggerSemi();   // 半自动：每次按下触发一次
        this.weapons.setFiring(true); // 自动：持续射击标记
        // 记录开火指针，用于"按住 FIRE 拖动也转视角"
        this._firePointerId = e.pointerId;
        this._fireLastX = e.clientX;
        this._fireLastY = e.clientY;
        if (btn.setPointerCapture) {
          try { btn.setPointerCapture(e.pointerId); } catch (err) { /* 忽略 */ }
        }
      };
      const move = (e) => {
        if (this._firePointerId === null || e.pointerId !== this._firePointerId) return;
        if (this.state !== 'playing') return;
        e.preventDefault();
        const dx = e.clientX - this._fireLastX;
        const dy = e.clientY - this._fireLastY;
        this._fireLastX = e.clientX;
        this._fireLastY = e.clientY;
        // 视角滑动方向映射与 _onDocTouchMove 一致（整页旋转 90° 后屏幕系→内容系）
        this.player.onTouchLook(
          this._rotated ? dy : dx,
          this._rotated ? -dx : dy
        );
      };
      const release = (e) => {
        e.preventDefault(); btn.classList.remove('active');
        this.weapons.setFiring(false);
        this._firePointerId = null;
      };
      btn.addEventListener('pointermove', move, { passive: false });
      bindPress(btn, press, release);
    });

    // 武器切换按钮：点一次循环 usp→ak47→awp（单按钮替代 3 个编号按钮，避免遮挡/可见问题）
    const WEAPON_CYCLE = ['usp', 'ak47', 'awp'];
    touchControls.querySelectorAll('[data-action="weapon-cycle"]').forEach(btn => {
      const tap = (e) => {
        e.preventDefault(); if (this._editLayout) return;
        btn.classList.add('active');
        const idx = WEAPON_CYCLE.indexOf(this.weapons.currentId);
        this.weapons.switchTo(WEAPON_CYCLE[(idx + 1) % WEAPON_CYCLE.length]);
        setTimeout(() => btn.classList.remove('active'), 200);
      };
      const noop = () => {};
      bindPress(btn, tap, noop);
    });

    // 暂停按钮
    touchControls.querySelectorAll('[data-action="pause"]').forEach(btn => {
      const tap = (e) => {
        e.preventDefault(); if (this._editLayout) return;
        btn.classList.add('active');
        if (this.state === 'playing') {
          this.state = 'paused';
          this.hud.showPause();
        }
        setTimeout(() => btn.classList.remove('active'), 200);
      };
      const noop = () => {};
      bindPress(btn, tap, noop);
    });

    // 设置齿轮：打开设置中心
    touchControls.querySelectorAll('[data-action="settings"]').forEach(btn => {
      const tap = (e) => {
        e.preventDefault(); if (this._editLayout) return;
        btn.classList.add('active');
        this._openSettings();
        setTimeout(() => btn.classList.remove('active'), 200);
      };
      const noop = () => {};
      bindPress(btn, tap, noop);
    });

    // AWP 开镜/关镜：点按切换（内部判断当前武器是否带 fov，非狙击无操作）
    touchControls.querySelectorAll('[data-action="scope"]').forEach(btn => {
      const tap = (e) => {
        e.preventDefault(); if (this._editLayout) return;
        btn.classList.add('active');
        this.weapons.toggleScopeZoom();
        setTimeout(() => btn.classList.remove('active'), 200);
      };
      const noop = () => {};
      bindPress(btn, tap, noop);
    });

    // 武器槽（右下角 HUD，桌面/移动通用）：点击直接换枪，解决移动端换枪不便
    document.querySelectorAll('#weaponSlots .slot').forEach(slot => {
      slot.addEventListener('click', () => {
        const idMap = { 1: 'usp', 2: 'ak47', 3: 'awp' };
      const id = idMap[parseInt(slot.dataset.slot)] || 'usp';
        this.weapons.switchTo(id);
      });
    });
  }

  // ---------- 设置中心：自定义控件布局 ----------
  // 布局数据 { size: 1, pos: { fire: {fx,fy}, ... } }，fx/fy 为内容尺寸的中心点分数（0~1），
  // 旋转/换机型重算像素仍成立；localStorage 容器内可用（device-capabilities 允许）
  _loadLayout() {
    try {
      const raw = localStorage.getItem('cs15_layout_v1');
      if (raw) {
        const d = JSON.parse(raw);
        return { size: (d.size >= 0.5 && d.size <= 1.6) ? d.size : 1, pos: d.pos || {} };
      }
    } catch (e) { /* localStorage 不可用时用内存态 */ }
    return { size: 1, pos: {} };
  }

  _saveLayout() {
    try { localStorage.setItem('cs15_layout_v1', JSON.stringify(this._layout)); } catch (e) { /* 忽略 */ }
  }

  _editableList() {
    if (this._editables) return this._editables;
    this._editables = [
      { key: 'fire',   el: document.querySelector('.fire-btn') },
      { key: 'jump',   el: document.getElementById('btnJump') },
      { key: 'crouch', el: document.getElementById('btnCrouch') },
      { key: 'reload', el: document.getElementById('btnReload') },
      { key: 'weapon', el: document.getElementById('btnWeaponCycle') },
      { key: 'scope',  el: document.getElementById('btnScope') },
      { key: 'pause',  el: document.querySelector('#topControls .top-btn[data-action="pause"]') },
      { key: 'gear',   el: document.querySelector('#topControls .top-btn[data-action="settings"]') },
      { key: 'joy',    el: document.getElementById('joyBase') },
    ].filter(x => x.el);
    // 记录原始位置：恢复默认布局时物归原父节点
    for (const it of this._editables) {
      it.origParent = it.el.parentNode;
      it.origNext = it.el.nextSibling;
    }
    return this._editables;
  }

  // 自定义定位公共路径：挂到 #touchControls（全屏、inset:0、无自身变换）下用 absolute 定位。
  // 不用 position:fixed——手机 WebView 常不把旋转容器当作 fixed 的包含块，
  // 内容坐标会被按未旋转的竖屏视口解释，left 超出竖屏宽度 → 按钮"消失"。
  // absolute 在旋转容器内的行为各内核一致。
  _placeCustom(el, x, y, scale) {
    const host = document.getElementById('touchControls');
    if (host && el.parentNode !== host) host.appendChild(el);
    el.style.position = 'absolute';
    el.style.left = x + 'px';
    el.style.top = y + 'px';
    el.style.right = ''; el.style.bottom = '';
    el.style.transform = 'translate(-50%, -50%) scale(' + scale + ')';
    el.style.zIndex = 60;
    // touchControls 本身 pointer-events:none，除摇杆示意圈外的自定义控件要显式可点
    el.style.pointerEvents = (el.id === 'joyBase') ? '' : 'auto';
  }

  // 恢复某控件的 CSS 默认布局（含物归原父节点）
  _restoreDefault(el, origParent, origNext) {
    if (origParent && el.parentNode !== origParent) {
      try { origParent.insertBefore(el, origNext); } catch (e) { origParent.appendChild(el); }
    }
    el.style.position = '';
    el.style.left = ''; el.style.top = '';
    el.style.right = ''; el.style.bottom = '';
    el.style.transform = ''; el.style.zIndex = '';
    el.style.pointerEvents = '';
  }

  // 应用自定义布局：有自定义位置的控件挂到全屏控制层用 absolute 定位；没有的恢复 CSS 默认
  _applyLayout() {
    const W = this._gw || window.innerWidth;
    const H = this._gh || window.innerHeight;
    const size = (this._layout && this._layout.size) || 1;
    this.gameRoot.style.setProperty('--ui-size', size);
    for (const { key, el, origParent, origNext } of this._editableList()) {
      const p = this._layout.pos && this._layout.pos[key];
      if (p && p.fx >= 0 && p.fy >= 0) {
        const s = (this._ctrlScale || 0.85) * size;
        this._placeCustom(el, p.fx * W, p.fy * H, s);
      } else {
        this._restoreDefault(el, origParent, origNext);
      }
    }
  }

  _bindSettings() {
    const menu = document.getElementById('settingsMenu');
    if (!menu) return;
    const slider = document.getElementById('uiSizeSlider');
    const val = document.getElementById('uiSizeVal');
    slider.value = Math.round((this._layout.size || 1) * 100);
    val.textContent = slider.value + '%';
    slider.addEventListener('input', () => {
      this._layout.size = slider.value / 100;
      val.textContent = slider.value + '%';
      this._saveLayout();
      this._applyLayout();
    });
    document.getElementById('layoutEditBtn').addEventListener('click', () => this._enterEditLayout());
    document.getElementById('layoutResetBtn').addEventListener('click', () => {
      this._layout = { size: 1, pos: {} };
      this._saveLayout();
      slider.value = 100; val.textContent = '100%';
      this._applyLayout();
    });
    document.getElementById('settingsCloseBtn').addEventListener('click', () => this._closeSettings());
    // 暂停菜单里也放一个设置入口（桌面端触屏控件隐藏时靠它进设置）
    const pauseSet = document.getElementById('pauseSettingsBtn');
    if (pauseSet) pauseSet.addEventListener('click', () => {
      this.hud.hidePause();
      this._openSettings();
    });
  }

  _openSettings() {
    this._settingsFromPlay = (this.state === 'playing');
    if (this.state === 'playing') this.state = 'paused';
    // 释放鼠标锁定，否则设置面板点不了（锁定会把所有点击重定向到画布）
    document.exitPointerLock?.();
    document.getElementById('settingsMenu').classList.remove('hidden');
  }

  _closeSettings() {
    document.getElementById('settingsMenu').classList.add('hidden');
    if (this._settingsFromPlay && this.state === 'paused') {
      this.state = 'playing';
      this._requestLock();
    } else if (this.state === 'paused') {
      this.hud.showPause();   // 从暂停菜单进来的：关设置回暂停界面
    }
  }

  _enterEditLayout() {
    document.getElementById('settingsMenu').classList.add('hidden');
    document.getElementById('layoutEditBar').classList.remove('hidden');
    this._editLayout = true;
    for (const { el } of this._editableList()) el.classList.add('edit-drag');
  }

  _exitEditLayout() {
    this._editLayout = false;
    document.getElementById('layoutEditBar').classList.add('hidden');
    for (const { el } of this._editableList()) el.classList.remove('edit-drag');
    this._saveLayout();
    this._applyLayout();
    if (this._settingsFromPlay && this.state === 'paused') {
      this.state = 'playing';
      this._requestLock();
    } else if (this.state === 'paused') {
      this.hud.showPause();
    }
  }

  // 编辑模式拖拽：Pointer 事件 + 捕获，拖动即改 fixed 中心点，松手存分数
  _bindLayoutEdit() {
    for (const { key, el } of this._editableList()) {
      el.addEventListener('pointerdown', (e) => {
        if (!this._editLayout) return;
        e.preventDefault();
        e.stopPropagation();
        if (el.setPointerCapture) {
          try { el.setPointerCapture(e.pointerId); } catch (err) { /* 忽略 */ }
        }
        const W = this._gw || window.innerWidth;
        const H = this._gh || window.innerHeight;
        const r = el.getBoundingClientRect();
        // 抓取点相对控件中心的偏移（屏幕系，拖动时控件不跳变）
        const grabX = e.clientX - (r.left + r.width / 2);
        const grabY = e.clientY - (r.top + r.height / 2);
        // 屏幕 → 内容坐标：整页旋转 90° 时 left/top 是内容坐标系，
        // 直接用屏幕 clientX/Y 会导致「往右拖按钮往下跑」——必须换算
        const toContent = (sx, sy) => (
          this._rotated
            ? { x: sy, y: H - sx }   // 旋转态：内容x=屏幕y，内容y=内容高-屏幕x
            : { x: sx, y: sy }
        );
        const apply = (sx, sy) => {
          const c = toContent(sx, sy);
          const x = Math.max(20, Math.min(W - 20, c.x));
          const y = Math.max(20, Math.min(H - 20, c.y));
          this._placeCustom(el, x, y, (this._ctrlScale || 0.85) * (this._layout.size || 1));
        };
        const move = (ev) => apply(ev.clientX - grabX, ev.clientY - grabY);
        const up = (ev) => {
          el.removeEventListener('pointermove', move);
          el.removeEventListener('pointerup', up);
          el.removeEventListener('pointercancel', up);
          const c = toContent(ev.clientX - grabX, ev.clientY - grabY);
          this._layout.pos[key] = {
            fx: Math.max(0, Math.min(1, c.x / W)),
            fy: Math.max(0, Math.min(1, c.y / H)),
          };
          this._saveLayout();
        };
        el.addEventListener('pointermove', move);
        el.addEventListener('pointerup', up);
        el.addEventListener('pointercancel', up);
      });
    }
    document.getElementById('layoutEditDone').addEventListener('click', () => this._exitEditLayout());
  }

  _requestLock() {
    try {
      const el = this.renderer.domElement;
      if (!el.requestPointerLock) return;
      const p = el.requestPointerLock();
      if (p && typeof p.catch === 'function') p.catch(() => {});
    } catch (e) { /* PointerLock 不可用（移动端/iframe），忽略 */ }
  }

  _resume() {
    if (this.state !== 'paused') return;
    this.hud.hidePause();
    this.state = 'playing';
    // PC 端尝试重新锁定鼠标；移动端无 PointerLock 则直接继续
    this._requestLock();
  }

  // 程序化室内环境贴图（PMREM）：几面明暗不同的墙面 + 顶部亮面，
  // 让金属枪械/装甲产生真实反射层次
  _buildEnvironment() {
    const pmrem = new THREE.PMREMGenerator(this.renderer);
    const room = new THREE.Scene();
    // 地面（暗）
    const floor = new THREE.Mesh(new THREE.BoxGeometry(10, 10, 10), new THREE.MeshBasicMaterial({ color: 0x1a1a1e }));
    floor.position.y = -5;
    room.add(floor);
    // 顶部大亮面（模拟天光，金属的高光反射源）
    const top = new THREE.Mesh(new THREE.PlaneGeometry(10, 10), new THREE.MeshBasicMaterial({ color: 0xffffff }));
    top.rotation.x = Math.PI / 2;
    top.position.y = 5;
    room.add(top);
    // 四周不同明度的墙面，提供反射层次
    const sideData = [
      { color: 0x9a9aa2, pos: [-5, 0, 0] },
      { color: 0x3a3a44, pos: [5, 0, 0] },
      { color: 0x22222a, pos: [0, 0, -5] },
      { color: 0x6a6a74, pos: [0, 0, 5] },
    ];
    for (const s of sideData) {
      const wall = new THREE.Mesh(new THREE.PlaneGeometry(10, 10), new THREE.MeshBasicMaterial({ color: s.color }));
      wall.position.set(...s.pos);
      wall.lookAt(0, 0, 0);
      room.add(wall);
    }
    const tex = pmrem.fromScene(room, 0.04).texture;
    pmrem.dispose();
    return tex;
  }

  _bindResize() {
    const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    const rotateHint = document.getElementById('rotateHint');
    let lastW = 0, lastH = 0, timer = null;

    // 强制旋转开关：URL 加 rotate=1 可在桌面调试旋转布局
    const forceRotate = /[?&]rotate=1/.test(window.location.search);

    const applySize = () => {
      // 尺寸来源优先 visualViewport（容器地址栏/工具条收放时它先于 innerWidth 更新），异常时退回 innerWidth
      const vv = window.visualViewport;
      const vw = (vv && vv.width >= 100) ? vv.width : window.innerWidth;
      const vh = (vv && vv.height >= 100) ? vv.height : window.innerHeight;
      // 以视口实际宽高判断竖屏（容器可能虚报 orientation 信号，视口尺寸不会骗人）
      const viewportPortrait = vh > vw;
      // 触屏 + 竖屏视口 → 整页旋转 90° 强制横屏（容器 WebView 无法自己转横屏）
      const shouldRotate = (isTouch && viewportPortrait) || forceRotate;
      this._rotated = shouldRotate;
      document.body.classList.toggle('rotated', shouldRotate);
      // 逻辑渲染尺寸：旋转态宽高互换，始终按横屏渲染
      const w = shouldRotate ? vh : vw;
      const h = shouldRotate ? vw : vh;

      // gameRoot 铺满视口；旋转态把「宽=视口高、高=视口宽」的内容顺时针转 90°
      const s = this.gameRoot.style;
      s.position = 'fixed'; s.top = '0'; s.left = '0';
      s.width = w + 'px';
      s.height = h + 'px';
      s.transformOrigin = '0 0';
      s.transform = shouldRotate ? 'rotate(90deg) translateY(-100%)' : 'none';

      // 控件缩放系数：以游戏内容短边（横屏高度）驱动，参考高度 460px。
      // 真机/容器逻辑尺寸差异大（旋转态高度=视口短边，容器视口可能更小），
      // 固定像素偏移会挤出屏幕或互相重叠，全部控件尺寸/偏移按此系数缩放
      const ctrlScale = Math.max(0.62, Math.min(1, Math.min(w, h) / 460));
      this._ctrlScale = ctrlScale;
      s.setProperty('--ctrl-scale', ctrlScale);
      s.setProperty('--gw', w + 'px');
      s.setProperty('--gh', h + 'px');

      const logicalPortrait = !shouldRotate && viewportPortrait;
      document.body.classList.toggle('portrait', logicalPortrait);
      document.body.classList.toggle('landscape', !logicalPortrait);
      // 仅真正以竖屏渲染时用加大 FOV 补偿窄视野；旋转态逻辑上是横屏
      // 开镜状态（AWP）优先：不因 resize 重置 FOV（真机 visualViewport resize 频繁，否则开镜瞬间被覆盖）
      const wDef = this.weapons && CONFIG.weapons[this.weapons.currentId];
      const scoped = this.weapons && this.weapons._scopeZoomed && wDef && wDef.fov;
      this.camera.fov = scoped ? wDef.fov : (logicalPortrait ? CONFIG.fovPortrait : CONFIG.fov);
      this.camera.aspect = w / h;
      this.camera.updateProjectionMatrix();
      // 像素比仅在变化时更新（触屏限 1.5 提帧，桌面限 2 保清晰）
      const dpr = Math.min(window.devicePixelRatio || 1, isTouch ? 1.5 : 2);
      if (this.renderer.getPixelRatio() !== dpr) this.renderer.setPixelRatio(dpr);
      // 尺寸变化时才 setSize，避免移动端 visualViewport resize 连发导致卡顿
      if (w !== lastW || h !== lastH) {
        lastW = w; lastH = h;
        this.renderer.setSize(w, h);
      }
      // 横屏提示显隐已由纯 CSS 媒体查询控制（触屏+竖屏自动显示；旋转态/横屏自动隐藏）
      // 自诊断（URL 加 ?debug=1）：显示视口/缩放/旋转，真机排查用
      const dbg = document.getElementById('debugBar');
      if (dbg && /[?&]debug=1/.test(window.location.search)) {
        document.body.classList.add('debug');
        dbg.textContent = `视口 ${Math.round(vw)}×${Math.round(vh)} | 内容 ${w|0}×${h|0} | 缩放 ${ctrlScale.toFixed(2)} | 旋转 ${shouldRotate ? '开' : '关'} | DPR ${window.devicePixelRatio}`;
      }

      // 记录内容尺寸并重应用自定义控件布局（分数→像素随尺寸重算）
      this._gw = w; this._gh = h;
      this._applyLayout();
    };

    // 防抖：orientationchange 期间浏览器会连发多次 resize/visualViewport resize
    const schedule = (delay) => { clearTimeout(timer); timer = setTimeout(applySize, delay || 80); };
    window.addEventListener('resize', () => schedule(80));
    if (window.visualViewport) window.visualViewport.addEventListener('resize', () => schedule(80));
    window.addEventListener('orientationchange', () => schedule(300));

    // 保底：手动跳过横屏提示（即使方向检测异常也能进入游戏；hidden 优先于媒体查询）
    const continueBtn = document.getElementById('continuePortraitBtn');
    if (continueBtn) continueBtn.addEventListener('click', () => {
      if (rotateHint) rotateHint.classList.add('hidden');
    });

    applySize();   // 初始化
    // 容器 WebView 尺寸可能在首帧后才稳定（晚到的布局），延迟再校准一次
    setTimeout(applySize, 400);
    setTimeout(applySize, 1200);
  }

  // ---------- 一局开始 ----------
  _beginRun() {
    this.audio.init();      // 用户手势内初始化音频
    this.hud.hideMenu();
    this.hud.hideResult();
    this.hud.hidePause();
    this.hud.show();

    // 重置玩家与武器
    this.player.reset(this.gameMap.spawns.player);
    this.weapons.reset();
    this.pickups.reset();
    this.hud.updateVitals(this.player.health, this.player.armor);
    this.hud.updateWeapon(CONFIG.weapons.usp, this.weapons.state);

    // 清掉旧敌人
    for (const en of this.enemies) en.dispose();
    this.enemies.length = 0;

    this.wave = 0;
    // 随机多关卡：每局随机总波次数
    this.totalWaves = Math.floor(CONFIG.waves.minWaves + Math.random() * (CONFIG.waves.maxWaves - CONFIG.waves.minWaves + 1));
    this.kills = 0;
    this.totalKills = 0;
    this.startTime = performance.now();
    this.state = 'playing';
    this._nextWave();

    this._requestLock();
  }

  _nextWave() {
    this.wave++;
    if (this.wave > this.totalWaves) {
      this._endRun(true);
      return;
    }
    const W = CONFIG.waves;
    // 随机生成本波参数（随机多关卡：人数/血量/速度每波浮动，人数/血量封顶防单局过长）
    const count = Math.min(W.maxCount ?? 99, Math.max(2, Math.round(
      W.baseCount + (this.wave - 1) * W.countPerWave + (Math.random() - 0.5) * 2 * W.countJitter
    )));
    const hp = Math.min(W.hpCap ?? 9999, Math.max(40, Math.round(
      (W.hpBase + (this.wave - 1) * W.hpPerWave) * (1 + (Math.random() - 0.5) * 2 * W.hpJitter)
    )));
    const speed = Math.min(
      W.speedMax ?? Infinity,
      Math.max(1.5, W.speedBase + (this.wave - 1) * W.speedPerWave + (Math.random() - 0.5) * 2 * W.speedJitter)
    );

    this.hud.toast(`第 ${this.wave} 关：${count} 名敌人`);
    this.audio.wave(this.wave);

    // 生成敌人队列（每个敌人随机出生点，且远离玩家）
    const pf = this.player.getFeet();
    this.spawnQueue = [];
    for (let i = 0; i < count; i++) {
      this.spawnQueue.push({
        pos: this.gameMap.randomSpawn(pf.x, pf.z, 14),
        hp,
        speed,
        name: W.names[Math.floor(Math.random() * W.names.length)],
      });
    }
    // 立即刷出前 2 个，其余间隔刷
    this._spawnFromQueue(2);
    this.spawnTimer = 2.5;
    this._refreshScore();
  }

  _spawnFromQueue(n) {
    for (let i = 0; i < n && this.spawnQueue.length > 0; i++) {
      const spec = this.spawnQueue.shift();
      const en = new Enemy(this.scene, this.gameMap, this.player, this.hud, {
        hp: spec.hp, speed: spec.speed, name: spec.name,
        pickups: this.pickups,   // 死亡掉落护甲
      });
      en.spawnAt(spec.pos);
      this.enemies.push(en);
    }
    this._refreshScore();
  }

  _refreshScore() {
    const alive = this.enemies.filter(e => e.alive).length + this.spawnQueue.length;
    this.hud.updateScore(alive, this.kills, this.wave);
  }

  // ---------- 主循环 ----------
  _loop() {
    requestAnimationFrame(() => this._loop());
    const now = performance.now();
    let dt = (now - this._lastTime) / 1000;
    this._lastTime = now;
    // 钳制 dt 防止切后台后大跳
    dt = Math.min(dt, 0.05);

    this._update(dt);
    this.renderer.render(this.scene, this.camera);
    this.hud.drawMinimap();
  }

  _update(dt) {
    if (this.state !== 'playing') return;

    // 玩家
    this.player.update(dt);
    // 武器
    this.weapons.update(dt);
    // 血包
    this.pickups.update(dt);

    // 敌人
    for (const en of this.enemies) en.update(dt);
    // 清理完全消失的敌人
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const en = this.enemies[i];
      if (!en.alive && !en.mesh.visible) {
        en.dispose();
        this.enemies.splice(i, 1);
      }
    }

    // 统计本帧击杀（对比上一帧血量总和简化处理 → 改用回调已在 weapon 内累加 kills）
    // 这里仅刷新计数
    this._refreshScore();

    // 间隔刷怪
    if (this.spawnQueue.length > 0) {
      this.spawnTimer -= dt;
      if (this.spawnTimer <= 0) {
        // 场上存活敌人少于阈值就再刷
        const aliveCount = this.enemies.filter(e => e.alive).length;
        if (aliveCount < 4) {
          this._spawnFromQueue(1);
          this.spawnTimer = 2.5;
        } else {
          this.spawnTimer = 1.0;
        }
      }
    }

    // 回合完成判定
    const aliveCount = this.enemies.filter(e => e.alive).length;
    if (this.spawnQueue.length === 0 && aliveCount === 0) {
      // 进入下一波（短暂延迟）
      this._waveCooldown = (this._waveCooldown ?? 0) + dt;
      if (this._waveCooldown > 2.0) {
        this._waveCooldown = 0;
        this._nextWave();
      }
    } else {
      this._waveCooldown = 0;
    }

    // 玩家死亡
    if (!this.player.alive) {
      this._endRun(false);
    }
  }

  _endRun(win) {
    this.state = 'over';
    document.exitPointerLock?.();
    this.hud.hideClickHint();
    const time = ((performance.now() - this.startTime) / 1000) | 0;
    const mm = String((time / 60) | 0).padStart(2, '0');
    const ss = String(time % 60).padStart(2, '0');
    // 用回调累加的 totalKills（敌人倒地动画结束后会从数组移除，不能靠遍历统计）
    const totalKills = this.totalKills || 0;
    if (win) this.audio.win(); else this.audio.lose();
    this.hud.showResult(win, {
      '通关回合': win ? `${this.totalWaves} / ${this.totalWaves}` : `${this.wave - 1} / ${this.totalWaves}`,
      '累计击杀': totalKills,
      '存活时间': `${mm}:${ss}`,
    });
  }
}

// 给 weapon 的 killFeed 回调累加 kills —— 通过监听 HUD 的事件过于复杂，
// 这里在 weapon 内部已调用 hud.killFeed；我们在 HUD 上挂个回调计数。
// 简化：重写 killFeed 包一层
const origKillFeed = HUD.prototype.killFeed;
HUD.prototype.killFeed = function (name) {
  origKillFeed.call(this, name);
  if (this._onKill) this._onKill();
};

// 启动
window.addEventListener('DOMContentLoaded', () => {
  const game = new Game();
  // 把击杀计入统计
  game.hud._onKill = () => {
    game.kills++;
    game.totalKills++;
  };
  window.__game = game;   // 调试用
});

// map.js —— 关卡几何与碰撞数据
// 构造一个 CS 风格的对称竞技场：CT 房 / T 房 / 中央长廊 + 多个掩体箱
// 对外暴露 GameMap 类：scene 中添加网格 + 提供 collide() 碰撞查询 + spawn 点
// 经典脚本（非 ES Module）：THREE / CONFIG 由前置脚本挂到 window 提供

// AABB 包围盒（轴对齐），用于碰撞与射线
class Box {
  constructor(minX, maxX, minZ, maxZ, minY = 0, maxY = 4) {
    this.minX = minX; this.maxX = maxX;
    this.minZ = minZ; this.maxZ = maxZ;
    this.minY = minY; this.maxY = maxY;
  }
  // 点是否在盒内（XZ 平面）
  containsXZ(x, z) {
    return x >= this.minX && x <= this.maxX && z >= this.minZ && z <= this.maxZ;
  }
  // 圆与 AABB 碰撞（XZ 平面），返回推开向量 {x,z} 或 null
  // 注意：圆心在盒内部时，最近点等于圆心自身，按半径差推出的向量是零向量——
  // 必须沿穿透最浅的轴整段推出到墙面之外，否则实体会永久卡在墙体里
  // （randomSpawn 的采样验证、spawnAt 的出生解算、卡墙解困的方向采样都依赖这里的正确性）
  resolveCircle(px, pz, radius) {
    const closestX = Math.max(this.minX, Math.min(px, this.maxX));
    const closestZ = Math.max(this.minZ, Math.min(pz, this.maxZ));
    const dx = px - closestX;
    const dz = pz - closestZ;
    const distSq = dx * dx + dz * dz;
    if (distSq >= radius * radius) return null;
    if (distSq > 1e-9) {
      const dist = Math.sqrt(distSq);
      const overlap = radius - dist;
      return { x: (dx / dist) * overlap, z: (dz / dist) * overlap };
    }
    // 圆心在盒内：算到四面墙外的距离（含半径），取最短方向整段推出
    const toLeft = px - this.minX + radius;
    const toRight = this.maxX - px + radius;
    const toFront = pz - this.minZ + radius;
    const toBack = this.maxZ - pz + radius;
    const m = Math.min(toLeft, toRight, toFront, toBack);
    if (m === toLeft) return { x: -m, z: 0 };
    if (m === toRight) return { x: m, z: 0 };
    if (m === toFront) return { x: 0, z: -m };
    return { x: 0, z: m };
  }
}

class GameMap {
  constructor(scene) {
    this.scene = scene;
    this.boxes = [];      // 碰撞体（墙、掩体）
    this.spawns = {
      player: new THREE.Vector3(-22, 0, 0),
      enemy: [
        new THREE.Vector3(22, 0, -6),
        new THREE.Vector3(22, 0, 6),
        new THREE.Vector3(18, 0, 0),
        new THREE.Vector3(26, 0, 0),
        new THREE.Vector3(24, 0, -10),
        new THREE.Vector3(24, 0, 10),
      ],
    };
    this.bounds = { minX: -32, maxX: 32, minZ: -20, maxZ: 20 };
    this._build();
  }

  // 给材质异步应用真实贴图（加载完成后替换，加载前用纯色兜底，避免黑帧）
  _applyTex(mat, key, repeatX, repeatY) {
    const url = window.TEX && window.TEX[key];
    if (!url) return;
    new THREE.TextureLoader().load(url, (tex) => {
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      if ('SRGBColorSpace' in THREE) tex.colorSpace = THREE.SRGBColorSpace;
      tex.repeat.set(repeatX, repeatY);
      tex.needsUpdate = true;
      mat.map = tex;
      mat.color.setHex(0xffffff);   // 贴图全显，避免被兜底颜色染色
      mat.needsUpdate = true;
    });
  }

  // 添加一块墙体并登记碰撞
  _addWall(x, z, w, d, h, color, opts = {}) {
    const geo = new THREE.BoxGeometry(w, h, d);
    const mat = new THREE.MeshStandardMaterial({
      color, roughness: opts.rough ?? 0.9, metalness: opts.metal ?? 0.0,
    });
    // 砖墙贴图：按主面尺寸平铺（真实 CC0 贴图，加载前用纯色兜底）
    const len = Math.max(w, d);
    this._applyTex(mat, 'brick', Math.max(1, Math.round(len / 1.5)), Math.max(1, Math.round(h / 1.5)));
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(x, h / 2, z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    this.scene.add(mesh);
    // AABB
    this.boxes.push(new Box(x - w / 2, x + w / 2, z - d / 2, z + d / 2, 0, h));
    return mesh;
  }

  _build() {
    // ---------- 地面 ----------
    const floorSize = 80;
    const floorGeo = new THREE.PlaneGeometry(floorSize, floorSize);
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0x6a6f78, roughness: 0.85, metalness: 0.0,
    });
    // 棋盘格纹路：用 CanvasTexture 生成
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 256;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#6a6f78'; ctx.fillRect(0, 0, 256, 256);
    ctx.fillStyle = '#5a5f68';
    for (let i = 0; i < 8; i++)
      for (let j = 0; j < 8; j++)
        if ((i + j) % 2 === 0) ctx.fillRect(i * 32, j * 32, 32, 32);
    floorMat.map = new THREE.CanvasTexture(canvas);
    floorMat.map.wrapS = floorMat.map.wrapT = THREE.RepeatWrapping;
    floorMat.map.repeat.set(20, 20);
    // 混凝土贴图（真实 CC0，替换棋盘格兜底）
    this._applyTex(floorMat, 'concrete', 20, 20);
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    this.scene.add(floor);

    // ---------- 天空（穹顶）----------
    const skyGeo = new THREE.SphereGeometry(200, 32, 16);
    const skyMat = new THREE.MeshBasicMaterial({
      color: 0x5a6a80, side: THREE.BackSide, fog: false,
    });
    this.scene.add(new THREE.Mesh(skyGeo, skyMat));

    // ---------- 外围墙 ----------
    const wallColor = 0x8a7560;
    const wallH = 5;
    // 东西两侧
    this._addWall(-32, 0, 1, 40, wallH, wallColor);   // 西墙
    this._addWall( 32, 0, 1, 40, wallH, wallColor);   // 东墙
    // 南北两侧
    this._addWall(0, -20, 64, 1, wallH, wallColor);
    this._addWall(0,  20, 64, 1, wallH, wallColor);

    // ---------- 中央长廊两侧墙（带门洞）----------
    // 中央走廊 Z ∈ [-4, 4]，在走廊外侧用墙隔出上下两个区域，并留门洞
    // 上半区隔墙（z=4），在 x ∈ [-6,6] 留门
    this._addWall(-19, 4, 26, 1, wallH, wallColor);   // x: -32~-6
    this._addWall( 19, 4, 26, 1, wallH, wallColor);   // x: 6~32
    // 下半区隔墙（z=-4）
    this._addWall(-19, -4, 26, 1, wallH, wallColor);
    this._addWall( 19, -4, 26, 1, wallH, wallColor);

    // ---------- 房间隔墙（CT 房在左 x≈-14，T 房在右 x≈14）----------
    // CT 房分隔：x=-14，留 z∈[-3,3] 门
    this._addWall(-14, 9.5, 1, 11, wallH, 0x7a6450);
    this._addWall(-14, -9.5, 1, 11, wallH, 0x7a6450);
    // T 房分隔：x=14
    this._addWall(14, 9.5, 1, 11, wallH, 0x7a6450);
    this._addWall(14, -9.5, 1, 11, wallH, 0x7a6450);

    // ---------- 掩体箱（AABB，可站上去/绕过）----------
    // 中央长廊掩体
    this._addCrate(0, 0, 2.2, 2.2, 1.2, 0xb88a4a);
    this._addCrate(-8, 0, 1.8, 1.8, 1.0, 0xb88a4a);
    this._addCrate(8, 0, 1.8, 1.8, 1.0, 0xb88a4a);
    // 上下区域掩体
    this._addCrate(-6, 11, 2.5, 1.5, 1.4, 0xa87a3a);
    this._addCrate(6, -11, 2.5, 1.5, 1.4, 0xa87a3a);
    this._addCrate(-22, 10, 2, 2, 1.2, 0xa87a3a);
    this._addCrate(22, -10, 2, 2, 1.2, 0xa87a3a);
    // 长廊角落小箱（半高，做胸墙）
    this._addCrate(-3, 7, 1.2, 1.2, 0.7, 0x906a2a);
    this._addCrate(3, -7, 1.2, 1.2, 0.7, 0x906a2a);

    // ---------- 光照 ----------
    // 环境光（提亮，让所有面都可见）
    this.scene.add(new THREE.AmbientLight(0xccddee, 1.8));
    // 半球光（上亮下暗，模拟天光）
    this.scene.add(new THREE.HemisphereLight(0xddeeff, 0x666a75, 1.2));
    // 主方向光（带阴影）
    const dir = new THREE.DirectionalLight(0xfff0d0, 1.4);
    dir.position.set(-20, 40, 20);
    dir.castShadow = true;
    dir.shadow.mapSize.set(CONFIG.shadowMapSize, CONFIG.shadowMapSize);
    dir.shadow.camera.left = -45; dir.shadow.camera.right = 45;
    dir.shadow.camera.top = 30; dir.shadow.camera.bottom = -30;
    dir.shadow.camera.near = 1; dir.shadow.camera.far = 100;
    dir.shadow.bias = -0.0005;
    this.scene.add(dir);
    // 反向补光（消除背光面阴影）
    const dir2 = new THREE.DirectionalLight(0xaabbcc, 0.6);
    dir2.position.set(20, 30, -20);
    this.scene.add(dir2);
    // 补光（点光源）增强氛围：3 个 → 2 个（去掉中央补光，由环境光/半球光保证亮度，减少逐像素光照开销）
    const p1 = new THREE.PointLight(0xffaa55, 1.0, 50, 2);
    p1.position.set(-24, 4, 0); this.scene.add(p1);
    const p2 = new THREE.PointLight(0x55aaff, 1.0, 50, 2);
    p2.position.set(24, 4, 0); this.scene.add(p2);

    // ---------- 背景与雾 ----------
    this.scene.background = new THREE.Color(0x3a4a5e);
    this.scene.fog = new THREE.Fog(0x3a4a5e, 80, 250);

    // ---------- 玩家出生点标记（不可见）----------
    // 已在 spawns 中
  }

  // 添加一个木箱掩体（AABB 含顶部高度，可踩）
  _addCrate(x, z, w, d, h, color) {
    const geo = new THREE.BoxGeometry(w, h, d);
    const mat = new THREE.MeshStandardMaterial({
      color, roughness: 0.85, metalness: 0.05,
    });
    // 木箱贴图（真实 CC0 木纹，加载前用纯色兜底）
    this._applyTex(mat, 'crateWood', 1, 1);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(x, h / 2, z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    this.scene.add(mesh);
    // 登记为可踩踏碰撞体（高度作为玩家头顶参考）
    this.boxes.push(new Box(x - w / 2, x + w / 2, z - d / 2, z + d / 2, 0, h));
  }

  // 碰撞解算：给定位置与半径，迭代推出所有重叠盒
  collide(px, pz, radius) {
    let x = px, z = pz;
    for (let i = 0; i < 3; i++) {   // 多次迭代提高稳定性
      for (const b of this.boxes) {
        const push = b.resolveCircle(x, z, radius);
        if (push) { x += push.x; z += push.z; }
      }
    }
    // 外围边界裁剪
    x = Math.max(this.bounds.minX + radius, Math.min(this.bounds.maxX - radius, x));
    z = Math.max(this.bounds.minZ + radius, Math.min(this.bounds.maxZ - radius, z));
    return { x, z };
  }

  // 随机可行走出生点：在地图内随机采样，避开碰撞盒与玩家（随机生成敌人位置）
  randomSpawn(avoidX, avoidZ, minDist) {
    for (let i = 0; i < 80; i++) {
      const x = this.bounds.minX + 1 + Math.random() * (this.bounds.maxX - this.bounds.minX - 2);
      const z = this.bounds.minZ + 1 + Math.random() * (this.bounds.maxZ - this.bounds.minZ - 2);
      if (minDist && avoidX !== undefined) {
        const dx = x - avoidX, dz = z - avoidZ;
        if (dx * dx + dz * dz < minDist * minDist) continue;
      }
      const r = this.collide(x, z, 0.6);
      if (Math.abs(r.x - x) < 0.001 && Math.abs(r.z - z) < 0.001) {
        return new THREE.Vector3(x, 0, z);
      }
    }
    // 回退：随机一个固定出生点
    const s = this.spawns.enemy[Math.floor(Math.random() * this.spawns.enemy.length)];
    return s.clone();
  }

  // 射线 vs 全部 AABB，返回最近相交点距离（保留旧接口，供敌人视线检测等使用）
  raycast(origin, direction, maxDist) {
    return this.raycastDetailed(origin, direction, maxDist).t;
  }

  // 高精度：返回 { t, normal }——最近命中距离 + 命中面世界法线（弹孔精确贴墙）
  raycastDetailed(origin, direction, maxDist) {
    let best = { t: maxDist, normal: null };
    for (const b of this.boxes) {
      const r = rayAABBDetailed(origin, direction, b);
      if (r !== null && r.t < best.t) best = r;
    }
    return best;
  }
}

// 射线 vs AABB（slab 法），返回 { t, normal } 或 null
// normal：被击中进入面的世界外法线（起点在盒内时为 null，调用方需回退）
function rayAABBDetailed(o, d, box) {
  let tmin = -Infinity, tmax = Infinity;
  let axis = null;   // 产生 tmin 的轴（进入面）
  // X
  if (Math.abs(d.x) > 1e-8) {
    let t1 = (box.minX - o.x) / d.x;
    let t2 = (box.maxX - o.x) / d.x;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tmin) { tmin = t1; axis = 'x'; }
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  } else if (o.x < box.minX || o.x > box.maxX) return null;
  // Y
  if (Math.abs(d.y) > 1e-8) {
    let t1 = (box.minY - o.y) / d.y;
    let t2 = (box.maxY - o.y) / d.y;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tmin) { tmin = t1; axis = 'y'; }
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  } else if (o.y < box.minY || o.y > box.maxY) return null;
  // Z
  if (Math.abs(d.z) > 1e-8) {
    let t1 = (box.minZ - o.z) / d.z;
    let t2 = (box.maxZ - o.z) / d.z;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tmin) { tmin = t1; axis = 'z'; }
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  } else if (o.z < box.minZ || o.z > box.maxZ) return null;

  if (tmax < 0) return null;
  const t = tmin >= 0 ? tmin : tmax;
  if (tmin < 0) return { t, normal: null };   // 起点在盒内，无进入面法线

  // 进入面法线：沿命中轴，符号与射线方向相反
  let sign = 0;
  if (axis === 'x') sign = d.x > 0 ? -1 : 1;
  else if (axis === 'y') sign = d.y > 0 ? -1 : 1;
  else if (axis === 'z') sign = d.z > 0 ? -1 : 1;
  const normal = new THREE.Vector3(
    axis === 'x' ? sign : 0,
    axis === 'y' ? sign : 0,
    axis === 'z' ? sign : 0
  );
  return { t, normal };
}

// 经典脚本全局暴露（依赖顺序：config → three(UMD) → map → …）
window.Box = Box;
window.GameMap = GameMap;

// player.js —— 第一人称玩家控制器
// 职责：PointerLock 鼠标视角、WASD 加速度移动、跳跃/重力、AABB 碰撞、血量护甲
// 采用 Source/CS 风格的速度向量积分（地面摩擦 + 空中受限控制）
// 经典脚本（非 ES Module）：THREE / CONFIG / clamp 由前置脚本挂到 window 提供

class Player {
  constructor(camera, gameMap, hud) {
    this.camera = camera;
    this.map = gameMap;
    this.hud = hud;
    const P = CONFIG.player;

    // 位置用 yaw/pitch 表示朝向，position 表示脚底
    this.position = new THREE.Vector3();
    this.velocity = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;
    this.onGround = true;

    // 状态
    this.health = P.maxHealth;
    this.armor = P.maxArmor;
    this.alive = true;
    this.crouching = false;

    // 输入
    this.keys = {};
    this.moveTouch = { x: 0, y: 0 };   // 虚拟摇杆模拟量（x 右 / y 前，-1~1）
    this._bindInput();

    // 视觉：手臂/枪模型挂在相机下，weapon 模块会注入
    this.recoilOffset = 0;     // 当前后坐力造成的视角上抬（用于恢复）
    this.viewBob = 0;          // 走路晃动相位
  }

  reset(spawn) {
    this.position.copy(spawn);
    this.velocity.set(0, 0, 0);
    this.yaw = 0; this.pitch = 0;
    this.onGround = true;
    this.health = CONFIG.player.maxHealth;
    this.armor = CONFIG.player.maxArmor;
    this.alive = true;
    this.moveTouch.x = 0; this.moveTouch.y = 0;
    this._syncCamera();
  }

  // ---------- 输入 ----------
  _bindInput() {
    this._onKeyDown = (e) => {
      this.keys[e.code] = true;
      // 防止 Space 滚动页面
      if (e.code === 'Space') e.preventDefault();
    };
    this._onKeyUp = (e) => { this.keys[e.code] = false; };
    window.addEventListener('keydown', this._onKeyDown);
    window.addEventListener('keyup', this._onKeyUp);
  }

  // 由 main 在 pointerlock 触发时调用
  onMouseMove(e) {
    if (!this.alive) return;
    const s = CONFIG.player.mouseSensitivity;
    this.yaw -= e.movementX * s;
    this.pitch -= e.movementY * s;
    this.pitch = clamp(this.pitch, -Math.PI / 2 + 0.01, Math.PI / 2 - 0.01);
  }

  // 触屏视角（灵敏度更高）
  onTouchLook(dx, dy) {
    if (!this.alive) return;
    const s = CONFIG.player.touchSensitivity;
    this.yaw -= dx * s;
    this.pitch -= dy * s;
    this.pitch = clamp(this.pitch, -Math.PI / 2 + 0.01, Math.PI / 2 - 0.01);
  }

  // ---------- 受伤 ----------
  takeDamage(amount) {
    if (!this.alive) return 0;
    let dmg = amount;
    // 护甲吸收 50%
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.5);
      this.armor -= absorbed;
      dmg -= absorbed;
    }
    this.health -= dmg;
    this.hud.damageFlash();
    if (this.health <= 0) {
      this.health = 0;
      this.alive = false;
    }
    this.hud.updateVitals(this.health, this.armor);
    return dmg;
  }

  heal(amount) {
    this.health = clamp(this.health + amount, 0, CONFIG.player.maxHealth);
    this.hud.updateVitals(this.health, this.armor);
  }

  // ---------- 主更新 ----------
  update(dt) {
    if (!this.alive) return;

    const P = CONFIG.player;
    // ---- 朝向（yaw 绕 Y，pitch 绕 X）----
    // 后坐力上抬叠加在 pitch 上
    this._syncCamera();

    // ---- 输入方向（局部空间）：键盘数字量 + 摇杆模拟量（x 右 / y 前，-1~1）----
    const fwd = (this.keys['KeyW'] ? 1 : 0) - (this.keys['KeyS'] ? 1 : 0) + this.moveTouch.y;
    const right = (this.keys['KeyD'] ? 1 : 0) - (this.keys['KeyA'] ? 1 : 0) + this.moveTouch.x;

    // 静步/蹲
    this.crouching = !!this.keys['ShiftLeft'] || !!this.keys['ControlLeft'];
    const wishSpeed = this.crouching ? P.crouchSpeed : P.walkSpeed;

    // 计算期望速度（基于 yaw，水平面）
    const sin = Math.sin(this.yaw), cos = Math.cos(this.yaw);
    // 相机 forward 在水平面：(-sin, 0, -cos)
    const wishX = (-sin * fwd + cos * right);
    const wishZ = (-cos * fwd - sin * right);
    const wishLen = Math.hypot(wishX, wishZ);
    const wishDirX = wishLen > 0 ? wishX / wishLen : 0;
    const wishDirZ = wishLen > 0 ? wishZ / wishLen : 0;
    const wishVelX = wishDirX * wishSpeed * (wishLen > 0 ? Math.min(wishLen, 1) : 0);
    const wishVelZ = wishDirZ * wishSpeed * (wishLen > 0 ? Math.min(wishLen, 1) : 0);

    // ---- 水平移动积分（CS 风格 accelerate + friction）----
    if (this.onGround) {
      // 摩擦：把当前水平速度向 0 衰减
      const speed = Math.hypot(this.velocity.x, this.velocity.z);
      if (speed > 0) {
        const drop = speed * P.friction * dt;
        const newSpeed = Math.max(0, speed - drop) / speed;
        this.velocity.x *= newSpeed;
        this.velocity.z *= newSpeed;
      }
      this._accelerate(wishDirX, wishDirZ, wishSpeed, P.accelGround, dt);
    } else {
      // 空中：受限加速（保留惯性）
      this._accelerate(wishDirX, wishDirZ, wishSpeed, P.accelAir, dt);
    }

    // ---- 跳跃 ----
    if (this.keys['Space'] && this.onGround) {
      this.velocity.y = P.jumpVelocity;
      this.onGround = false;
    }

    // ---- 重力 ----
    this.velocity.y -= P.gravity * dt;

    // ---- 位置积分 + 碰撞 ----
    // 先积分位置
    this.position.x += this.velocity.x * dt;
    this.position.z += this.velocity.z * dt;
    // XZ 碰撞解算
    const resolved = this.map.collide(this.position.x, this.position.z, P.radius);
    // 如果被推开，说明撞墙，清除该方向速度（简单处理）
    const pushX = resolved.x - this.position.x;
    const pushZ = resolved.z - this.position.z;
    if (Math.abs(pushX) > 0.001 || Math.abs(pushZ) > 0.001) {
      // 沿法线反弹掉该分量
      const nLen = Math.hypot(pushX, pushZ) || 1;
      const nx = pushX / nLen, nz = pushZ / nLen;
      const vDotN = this.velocity.x * nx + this.velocity.z * nz;
      if (vDotN < 0) {
        this.velocity.x -= vDotN * nx;
        this.velocity.z -= vDotN * nz;
      }
      this.position.x = resolved.x;
      this.position.z = resolved.z;
    }

    // Y 轴：地面 y=0
    this.position.y += this.velocity.y * dt;
    if (this.position.y <= 0) {
      this.position.y = 0;
      this.velocity.y = 0;
      this.onGround = true;
    }

    // ---- 视角晃动（走路 bob）----
    const hSpeed = Math.hypot(this.velocity.x, this.velocity.z);
    if (this.onGround && hSpeed > 0.5) {
      this.viewBob += dt * hSpeed * 1.4;
    } else {
      this.viewBob *= 0.9;
    }

    // ---- 后坐力恢复（数据驱动：recover 速率由当前武器提供，H-6 修复） ----
    if (this.recoilOffset > 0) {
      const recover = Math.min(this.recoilOffset, dt * (this.recoilRecover || 0.06));
      this.recoilOffset -= recover;
      this.pitch += recover;     // 恢复时 pitch 回正（注意 add）
    }

    this._syncCamera();
  }

  // 沿期望方向加速
  _accelerate(wishDirX, wishDirZ, wishSpeed, accel, dt) {
    const currentSpeed = this.velocity.x * wishDirX + this.velocity.z * wishDirZ;
    const addSpeed = wishSpeed - currentSpeed;
    if (addSpeed <= 0) return;
    let accelSpeed = accel * wishSpeed * dt;
    if (accelSpeed > addSpeed) accelSpeed = addSpeed;
    this.velocity.x += accelSpeed * wishDirX;
    this.velocity.z += accelSpeed * wishDirZ;
  }

  // 施加一发射击的后坐力（数据驱动：recover 恢复速率 + pattern 摆动幅度）
  applyRecoil(recoilDef) {
    this.pitch -= recoilDef.x;          // 上抬（pitch 减小=向上）
    this.recoilOffset += recoilDef.x;
    const sway = recoilDef.pattern === 'heavy' ? 1.6 : 1.0;   // AK 左右摆动更明显
    this.yaw += (Math.random() - 0.5) * 2 * recoilDef.y * sway;
    this.recoilRecover = recoilDef.recover ?? 0.06;           // 存本次恢复速率
    this.pitch = clamp(this.pitch, -Math.PI / 2 + 0.01, Math.PI / 2 - 0.01);
  }

  // 增加护盾点数（护甲拾取）：封顶 maxArmor
  addArmor(amount) {
    const P = CONFIG.player;
    this.armor = clamp(this.armor + amount, 0, P.maxArmor);
    this.hud.updateVitals(this.health, this.armor);
  }

  _syncCamera() {
    const P = CONFIG.player;
    const bobY = Math.sin(this.viewBob * 2) * 0.04 * (this.onGround ? 1 : 0);
    const bobX = Math.cos(this.viewBob) * 0.03 * (this.onGround ? 1 : 0);
    this.camera.position.set(
      this.position.x + bobX * 0.3,
      this.position.y + P.height + bobY,
      this.position.z
    );
    // 用欧拉角 YXZ 避免万向锁
    this.camera.rotation.set(this.pitch, this.yaw, 0, 'YXZ');
  }

  // 提供给武器模块：相机朝向射线
  // 起点用"无走路晃动"的眼位（bob 只影响渲染位置），保证弹道与屏幕中心准星严格重合
  getAimRay() {
    const dir = new THREE.Vector3(0, 0, -1);
    dir.applyEuler(new THREE.Euler(this.pitch, this.yaw, 0, 'YXZ'));
    return {
      origin: new THREE.Vector3(this.position.x, this.position.y + CONFIG.player.height, this.position.z),
      direction: dir.normalize(),
    };
  }

  // 提供给敌人：脚底位置
  getFeet() { return this.position; }
  getEye() { return this.camera.position; }

  dispose() {
    window.removeEventListener('keydown', this._onKeyDown);
    window.removeEventListener('keyup', this._onKeyUp);
  }
}

// 经典脚本全局暴露（依赖顺序：config → three(UMD) → map → player → …）
window.Player = Player;
